import manifest from './image-manifest.json';

export type ImageName = keyof typeof manifest;

const base = import.meta.env.BASE_URL;

/** Responsive attributes for an image generated by `npm run images`. */
export function imageSet(name: ImageName) {
  const { widths, width, height } = manifest[name];
  const largest = widths[widths.length - 1];
  return {
    src: `${base}images/${name}-${largest}.webp`,
    srcSet: widths.map((w) => `${base}images/${name}-${w}.webp ${w}w`).join(', '),
    width,
    height,
  };
}
